#!/usr/bin/env python3
"""Make a dependency-free Canvas viewer from the generated surface viewer data."""
from __future__ import annotations
import argparse, base64, gzip, json, math, re
from pathlib import Path

PAGE = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>SMPL surface contact Canvas viewer</title><style>
html,body{margin:0;height:100%;font:14px system-ui,"Microsoft YaHei",sans-serif;background:#eef2f4;color:#17212b}.app{height:100%;display:grid;grid-template-rows:auto 1fr auto}.top,.bottom{background:#fff;padding:10px 14px;border-bottom:1px solid #ccd6dc}.top{display:flex;justify-content:space-between}.top h1{margin:0;font-size:18px}.top p{margin:3px 0;color:#65737d}.main{min-height:0;display:grid;grid-template-columns:1fr 270px}.view{min-width:0;min-height:0;background:#edf1f3}.view canvas{width:100%;height:100%;display:block}.side{background:#fff;border-left:1px solid #ccd6dc;padding:12px;overflow:auto}.side h2{font-size:14px;margin:0 0 8px}.side section+section{border-top:1px solid #e4e9ec;margin-top:12px;padding-top:12px}.metrics div{display:flex;justify-content:space-between;margin:5px 0}.metrics dt{color:#65737d}.metrics dd{margin:0;text-align:right}.checks{display:grid;gap:7px}.bottom{display:flex;gap:10px;align-items:center;border-top:1px solid #ccd6dc;border-bottom:0}.bottom input{flex:1}.badge{padding:4px 8px;border-radius:10px;background:#e3edf2;color:#175b75}button{padding:5px 9px;border:1px solid #aebbc2;border-radius:5px;background:white}button.play{color:white;background:#176b7e}
</style><div class="app"><header class="top"><div><h1>male SMPL 表面手脚接触拟合</h1><p>Canvas 本地兼容版 · 窗口 60..90 · 31 帧 · 无外部库</p></div><div><span id="stage" class="badge">—</span> <span id="frame">60 / 90</span></div></header><div class="main"><div class="view"><canvas id="cv"></canvas></div><aside class="side"><section><h2>当前帧</h2><dl class="metrics"><div><dt>COCO 3D 误差</dt><dd id="e3">—</dd></div><div><dt>手部 surface 中位</dt><dd id="hr">—</dd></div><div><dt>脚部 surface 中位</dt><dd id="fr">—</dd></div><div><dt>地面变换</dt><dd id="pose">—</dd></div></dl></section><section><h2>显示</h2><div class="checks"><label><input id="mesh" type="checkbox" checked> SMPL 表面</label><label><input id="walker" type="checkbox" checked> 助步器</label><label><input id="handles" type="checkbox" checked> 扶手 capsule</label><label><input id="contact" type="checkbox"> sole/palm 点</label><label><input id="tri" type="checkbox" checked> 三角化点</label></div></section><section><h2>操作</h2><p>拖动旋转，滚轮缩放，底部滑块切帧。手部全帧损失是拟合假设，页面不代表真实握持。</p></section></aside></div><footer class="bottom"><button id="play" class="play">播放</button><input id="slider" type="range" min="0" max="30" value="0"><button id="reset">重置视角</button></footer></div><script id="data" type="application/json">DATA</script><script>
const d=JSON.parse(document.getElementById('data').textContent),canvas=document.getElementById('cv'),ctx=canvas.getContext('2d');const unpack=s=>new Float32Array(Uint8Array.from(atob(s),c=>c.charCodeAt(0)).buffer);Promise.all([unpack(d.v),unpack(d.w),unpack(d.t),unpack(d.he)]).then(([v,w,t,he])=>{const N=d.n,NV=d.nv,faces=d.faces,si=d.si,pi=d.pi,WN=d.wn.length;let fi=0,yaw=0.4,pitch=0.4,zoom=1.0,drag=false,lastX=0,lastY=0,playing=false,lastT=0;function gv(i){return [v[fi*NV*3+3*i],-v[fi*NV*3+3*i+1],v[fi*NV*3+3*i+2]]}function project(p){const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);let x=p[0]*cy-p[1]*sy,y=p[0]*sy+p[1]*cy,z=p[2];let yy=(z-.85)*cp-y*sp,zz=(z-.85)*sp+y*cp;const s=Math.min(canvas.width,canvas.height)*.9*zoom/(2.0+zz*.15);return [canvas.width*.5+x*s,canvas.height*.56-yy*s,zz]}function seg(a,b,color,width=2){const A=project(a),B=project(b);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(A[0],A[1]);ctx.lineTo(B[0],B[1]);ctx.stroke()}function draw(){const W=canvas.clientWidth*devicePixelRatio,H=canvas.clientHeight*devicePixelRatio;if(canvas.width!==W||canvas.height!==H){canvas.width=W;canvas.height=H}ctx.clearRect(0,0,W,H);ctx.fillStyle='#edf1f3';ctx.fillRect(0,0,W,H);ctx.save();ctx.globalAlpha=.8;for(let k=-4;k<=4;k++){seg([k,-4,0],[k,4,0],'#d3dcdf',1);seg([-4,k,0],[4,k,0],'#d3dcdf',1)}ctx.restore();if(document.getElementById('mesh').checked){const tris=[];for(const f of faces){const a=gv(f[0]),b=gv(f[1]),c=gv(f[2]),A=project(a),B=project(b),C=project(c);tris.push([A[2]+B[2]+C[2],A,B,C])}tris.sort((a,b)=>b[0]-a[0]);ctx.globalAlpha=.45;for(const q of tris){ctx.fillStyle=`hsl(${28+Math.max(0,Math.min(1,q[3][1]/H))*22},45%,58%)`;ctx.beginPath();ctx.moveTo(q[1][0],q[1][1]);ctx.lineTo(q[2][0],q[2][1]);ctx.lineTo(q[3][0],q[3][1]);ctx.closePath();ctx.fill()}ctx.globalAlpha=1}if(document.getElementById('walker').checked){for(const e of d.we){const a=wn(e[0]),b=wn(e[1]);seg(a,b,'#176b7e',3)}}if(document.getElementById('handles').checked){for(let s=0;s<2;s++)seg([he[fi*12+s*6],-he[fi*12+s*6+1],he[fi*12+s*6+2]],[he[fi*12+s*6+3],-he[fi*12+s*6+4],he[fi*12+s*6+5]],s?'#6a1b9a':'#f57c00',5)}if(document.getElementById('contact').checked){for(const idx of si){const q=project(gv(idx));ctx.fillStyle='#0b8043';ctx.beginPath();ctx.arc(q[0],q[1],2.5,0,7);ctx.fill()}for(const idx of pi){const q=project(gv(idx));ctx.fillStyle='#8e24aa';ctx.beginPath();ctx.arc(q[0],q[1],2,0,7);ctx.fill()}}if(document.getElementById('tri').checked){for(let j=0;j<17;j++)if(d.acc[fi*17+j]){const p=[t[fi*51+3*j],-t[fi*51+3*j+1],t[fi*51+3*j+2]],q=project(p);ctx.fillStyle='#c62828';ctx.beginPath();ctx.arc(q[0],q[1],3,0,7);ctx.fill()}}document.getElementById('stage').textContent=d.stage[fi];document.getElementById('frame').textContent=`${d.ids[fi]} / ${d.ids[N-1]}`;document.getElementById('e3').textContent=(d.e3[fi]===null?'—':d.e3[fi].toFixed(1)+' mm');document.getElementById('hr').textContent=(d.hm[fi]===null?'—':(d.hm[fi]*1000).toFixed(1)+' mm');document.getElementById('fr').textContent=(d.fm[fi]===null?'—':(d.fm[fi]*1000).toFixed(1)+' mm');document.getElementById('pose').textContent=d.pose[fi];}function wn(i){return [w[fi*WN*3+3*i],-w[fi*WN*3+3*i+1],w[fi*WN*3+3*i+2]]}document.getElementById('slider').oninput=e=>{fi=+e.target.value;playing=false;document.getElementById('play').textContent='播放';draw()};document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'暂停':'播放'};document.getElementById('reset').onclick=()=>{yaw=.4;pitch=.4;zoom=1;draw()};document.querySelectorAll('.checks input').forEach(x=>x.onchange=draw);canvas.onpointerdown=e=>{drag=true;lastX=e.clientX;lastY=e.clientY};onpointerup=()=>drag=false;onpointermove=e=>{if(drag){yaw+=(e.clientX-lastX)*.01;pitch+=(e.clientY-lastY)*.01;lastX=e.clientX;lastY=e.clientY;draw()}};canvas.onwheel=e=>{e.preventDefault();zoom*=e.deltaY<0?1.08:.93;draw()};function loop(t){if(playing&&t-lastT>33){fi=(fi+1)%N;document.getElementById('slider').value=fi;lastT=t;draw()}requestAnimationFrame(loop)}onresize=draw;draw();loop(0)}).catch(e=>{document.body.insertAdjacentHTML('beforeend','<pre style="color:#b00;padding:20px">Viewer initialization failed: '+e+'</pre>')});
</script></html>'''

def main() -> int:
    p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();s=a.source.read_text(encoding='utf-8');m=re.search(r'<script id="data" type="application/json">(.*?)</script>',s,re.S)
    if not m: raise RuntimeError('source viewer has no embedded data')
    data=json.loads(m.group(1))
    for key in ('v','w','t','he'):
        data[key]=base64.b64encode(gzip.decompress(base64.b64decode(data[key]))).decode('ascii')
    def finite_json(value):
        if isinstance(value,float) and not math.isfinite(value): return None
        if isinstance(value,list): return [finite_json(x) for x in value]
        if isinstance(value,dict): return {k:finite_json(v) for k,v in value.items()}
        return value
    data=finite_json(data)
    a.output.write_text(PAGE.replace('DATA',json.dumps(data,ensure_ascii=False,allow_nan=False,separators=(',',':'))),encoding='utf-8');print(a.output.resolve());return 0
if __name__=='__main__':raise SystemExit(main())
